/* NESTE 1.0 — fully offline personal action coach.
   No external analytics, network calls or AI endpoints. */
(() => {
'use strict';
const KEY='neste_state_v1';
const LABELS={family:'Familie og hjem',work:'Arbeid',training:'Trening',learn:'Læring',memory:'Hukommelse',phone:'Skjermtid',recovery:'Restitusjon'};
const DESCRIPTIONS={family:'Se behov, ta initiativ og være til stede.',work:'Starte tidligere og handle med mer trygghet.',training:'Styrke, mobilitet og jevn bevegelse.',learn:'Lære noe nytt i små, overkommelige steg.',memory:'Færre løse tråder og bedre repetisjon.',phone:'Mer bevisst bruk og flere skjermfrie øyeblikk.',recovery:'Tilpasse ambisjonene til søvn og overskudd.'};
const SYMBOLS={family:'heart',work:'briefcase',training:'activity',learn:'book',memory:'brain',phone:'phone',recovery:'moon'};
const DAYS=['søndag','mandag','tirsdag','onsdag','torsdag','fredag','lørdag'];
const SHORT_DAYS=['søn','man','tir','ons','tor','fre','lør'];
const ACTIONS=[
 ['f1','family','Spør hva som vil gjøre kvelden lettere','Ta fem minutter og spør samboeren hva som ville vært en konkret avlastning i kveld. Følg opp én ting.',2,'Du trener på å ta initiativ framfor å vente på at noe blir bedt om.'],
 ['f2','family','Gjør én usynlig oppgave synlig','Se på morgendagens logistikk: klær, matpakke, beskjeder eller avtaler. Ordne én konkret ting.',2,'Små grep før behovet blir akutt gjør hverdagen lettere.'],
 ['f3','family','Ti minutter helt til stede','Legg telefonen et annet sted og la barnet styre lek eller samtale i ti minutter.',2,'Avgrenset, uforstyrret oppmerksomhet er mer realistisk enn å kreve full tilstedeværelse hele tiden.'],
 ['f4','family','Ta eierskap til én ting','Velg et konkret område hjemme som du følger opp fra start til slutt denne uken.',3,'Proaktivitet blir lettere når ansvar er tydelig definert.'],
 ['f5','family','Legg merke til hva som trengs','Gå gjennom ett rom og finn én ting som bør gjøres. Bruk to minutter på den.',1,'Å øve på å se behov er også fremgang, selv når handlingen er liten.'],
 ['f6','family','Vær nærværende i fem minutter','Legg bort telefonen og vær tilgjengelig for samboer eller barn i fem rolige minutter.',1,'Målet er en liten handling du faktisk kan gjøre også på en slitsom dag.'],
 ['w1','work','Start på det du har utsatt','Velg én ubehagelig arbeidsoppgave og jobb med den i 15 minutter før du finpusser planen.',3,'Det å begynne før du føler deg helt klar kan bryte utsettelsesmønsteret.'],
 ['w2','work','Ta en beslutning med 70 % klarhet','Velg en liten reverserbar beslutning. Sett en frist, skriv ned kriteriet og bestem deg.',3,'Ikke alle beslutninger trenger mer analyse; start med dem som kan justeres.'],
 ['w3','work','Send den første avklaringen','Finn én sak du venter med. Send spørsmålet som kan få den videre.',2,'En tydelig avklaring kan være mer verdt enn ytterligere grubling.'],
 ['w4','work','Definer første synlige steg','Skriv ned det aller første fysiske steget i et nytt eller uoversiktlig arbeidsprosjekt.',2,'En konkret handling er lettere å starte enn en abstrakt oppgave.'],
 ['w5','work','Åpne én vanskelig sak','Åpne dokumentet eller samtalen du vegrer deg for. Skriv en setning om neste handling.',1,'Du trenger ikke fullføre for å flytte terskelen for å komme i gang.'],
 ['w6','work','To minutter før e-posten','Bruk to minutter på én prioritert oppgave før du går inn i innboksen.',1,'Et lite initiativ tidlig kan gjøre dagen mindre reaktiv.'],
 ['t1','training','En kort økt som faktisk blir gjort','Sett av 15 minutter til styrke eller mobilitet hjemme. Juster belastning til dagsform.',3,'Kontinuitet er viktigere enn en perfekt økt.'],
 ['t2','training','Planlegg neste treningsvindu','Velg et realistisk tidspunkt for en kort treningsøkt og noter det i planen.',2,'Å knytte aktiviteten til et bestemt tidspunkt kan gjøre start enklere.'],
 ['t3','training','Gjør en rolig bevegelsesøkt','Bruk ti minutter på kontrollert og komfortabel bevegelighet for hofte og bakside lår.',2,'Rolig, jevn praksis passer bedre enn å presse svært stive ledd hardt.'],
 ['t4','training','Fem minutter på gulvet','Gjør fem minutter rolig bevegelse, innenfor det som kjennes greit.',1,'Dette teller som å holde vanen i live.'],
 ['t5','training','En kort tur ute','Gå en rolig tur i fem til ti minutter, uten tempo- eller distansekrav.',1,'Lavterskel aktivitet kan være lettere å gjennomføre på dager med lite søvn.'],
 ['l1','learn','Lær én ting og gjenfortell den','Bruk ti minutter på en sak du er nysgjerrig på. Lukk kilden og forklar ett poeng med egne ord.',2,'Aktiv gjenhenting er ofte mer nyttig for hukommelsen enn passiv lesing.'],
 ['l2','learn','Still et bedre spørsmål','Velg en ting du ikke forstår i jobb eller hverdag. Finn et godt spørsmål og undersøk svaret.',2,'Nysgjerrighet trenger ikke et stort læringsprosjekt.'],
 ['l3','learn','Tre minutter med ny kunnskap','Les eller lytt i tre minutter. Skriv ned én ting du vil huske.',1,'Små læringsøkter er en god start når energien er begrenset.'],
 ['m1','memory','Få én løs tråd ut av hodet','Noter én avtale, oppgave eller bekymring på et sted du faktisk ser igjen.',1,'Et eksternt system kan avlaste hukommelsen uten at du må huske mer.'],
 ['m2','memory','Hent fram noe du lærte','Tenk tilbake på noe du lærte nylig. Prøv å forklare det uten å slå det opp.',2,'Gjenhenting styrker tilgjengeligheten til det du har lært.'],
 ['m3','memory','Lag en huskeregel for i morgen','Skriv ned hva som må skje i morgen, og knytt det til et tidspunkt eller en kjent rutine.',2,'En konkret trigger fungerer ofte bedre enn et løst ønske om å huske.'],
 ['p1','phone','Legg bort telefonen når du kommer hjem','Ha en telefonfri halvtime i starten av tiden hjemme. Legg enheten utenfor rekkevidde.',2,'Det er lettere å endre omgivelsene enn å stole på selvkontroll hver gang.'],
 ['p2','phone','Finn ett automatisk scroll-øyeblikk','Legg merke til neste gang du åpner en app uten et tydelig formål. Lukk den og velg bevisst.',2,'Å oppdage utløsere kan være første skritt mot endring.'],
 ['p3','phone','Ti minutter uten skjerm','Velg ett ti-minuttersrom i dag der telefonen ligger i et annet rom.',1,'Et kort skjermfritt intervall er bedre enn en streng regel du ikke orker å følge.'],
 ['r1','recovery','Senk lista for én ting','Velg én oppgave du kan gjøre enklere, utsette bevisst eller overlate til et senere tidspunkt.',1,'Restitusjon handler også om å redusere belastning, ikke bare legge til tiltak.'],
 ['r2','recovery','Beskytt en rolig overgang','Sett av ti minutter uten nye krav etter arbeid eller før leggetid.',1,'En liten overgang kan bidra til å redusere følelsen av å alltid være på.'],
 ['r3','recovery','Legg deg litt tidligere hvis det er mulig','Velg én kveldsaktivitet du kan kutte ned for å gi søvnen bedre plass.',2,'Når søvnen er oppstykket, kan belastningsstyring være viktigere enn mer selvdisiplin.'],
];
const actionById=Object.fromEntries(ACTIONS.map(a=>[a[0],{id:a[0],area:a[1],title:a[2],description:a[3],effort:a[4],why:a[5]}]));
const icons={
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',
 chart:'<path d="M3 3v18h18"/><path d="M7 16v-5m5 5V7m5 9V4"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
 user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 3-6 8-6s8 2 8 6"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 heart:'<path d="M20.8 8.6c0 4.3-8.8 10.4-8.8 10.4S3.2 12.9 3.2 8.6a5 5 0 0 1 8.8-3.2 5 5 0 0 1 8.8 3.2Z"/>',
 briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>',
 activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',
 book:'<path d="M12 7c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V6c-3-1-6-1-9 1ZM12 7v14"/>',
 brain:'<path d="M12 6c0-4-6-4-7 0-3 0-3 5-1 6-2 3 0 6 3 6 1 4 5 3 5 0V6Zm0 0c0-4 6-4 7 0 3 0 3 5 1 6 2 3 0 6-3 6-1 4-5 3-5 0V6Z"/>',
 phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4"/>',
 moon:'<path d="M20 15A8 8 0 0 1 9 4a8 8 0 1 0 11 11Z"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4m11.4-11.4 1.4-1.4"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M4.9 4.9l2.1 2.1m10 10 2.1 2.1M4.9 19.1 7 17m10-10 2.1-2.1"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 close:'<path d="M5 5l14 14M19 5 5 19"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',
 refresh:'<path d="M20 8V4l-3 3a8 8 0 1 0 2 8M20 4h-5"/>',
 export:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 spark:'<path d="m12 2-2 7-7 3 7 2 2 8 2-8 7-2-7-3z"/>',
 shield:'<path d="m12 2 9 4v6c0 5-4 8-9 10-5-2-9-5-9-10V6Z"/>',
 pause:'<path d="M8 5v14M16 5v14"/>',
 play:'<path d="m7 4 13 8-13 8z"/>',
 minus:'<path d="M5 12h14"/>',
 trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6M10 10v7m4-7v7"/>',
};
function ico(name,cls=''){return `<span class="icon ${cls}"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg></span>`;}
function esc(x){return String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function localDay(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function dateFromKey(s){const a=s.split('-').map(Number);return new Date(a[0],a[1]-1,a[2],12);}
function dayLabel(s){return new Intl.DateTimeFormat('nb-NO',{weekday:'long',day:'numeric',month:'long'}).format(dateFromKey(s));}
function seed(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0;}
function defaultState(){return {schema:1,onboarded:false,name:'',areas:{family:3,work:3,training:3,learn:1,memory:2,phone:2,recovery:3},cards:[],reminders:{morning:{time:'08:15',on:true},home:{time:'17:00',on:true},evening:{time:'20:45',on:false}},plans:{},logs:{},tasks:[],createdAt:new Date().toISOString(),settings:{compact:false}};}
function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return defaultState();const x=JSON.parse(raw);if(!x||x.schema!==1||!x.areas||!x.logs||!x.plans)throw Error('Invalid state');const def=defaultState();return {...def,...x,areas:{...def.areas,...x.areas},reminders:{...def.reminders,...x.reminders},cards:Array.isArray(x.cards)?x.cards:[]};}catch(e){console.warn('Could not read saved state',e);return defaultState();}}
let state=load(), screen='today', modal='', modalData={}, showWhy=false, period='week', timer={until:0,interval:null}, onboardingStep=0;
const today=()=>localDay();
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('Kunne ikke lagre data på denne enheten.');return false}}
function recentActivity(){return Object.entries(state.logs).sort((a,b)=>b[0].localeCompare(a[0])).filter(([_,v])=>v&&v.result);}
function daysSince(area,date){const last=Object.entries(state.plans).filter(([d,p])=>d<date&&p?.area===area).sort((a,b)=>b[0].localeCompare(a[0]))[0];return last?Math.min(9,Math.round((dateFromKey(date)-dateFromKey(last[0]))/86400000)):7;}
function resolvedAction(id){if(id&&id.startsWith('task:')){const task=state.tasks.find(t=>t.id===id.slice(5));if(task)return {id,area:task.area,title:'Ta tak i: '+task.title,description:'Dette er noe du selv vil følge opp. Gjør det første konkrete steget i dag, selv om det tar bare fem minutter.',effort:2,why:'Du har gitt denne oppgaven en dato. Å handle før det blir akutt kan redusere følelsen av å henge etter.'};}return actionById[id]||actionById.r1;}
function computePlan(date){const due=state.tasks.filter(t=>!t.done&&t.due&&t.due<=date).sort((a,b)=>a.due.localeCompare(b.due));if(due.length){return {area:due[0].area,actionId:'task:'+due[0].id};}
 const day=dateFromKey(date).getDay();const log=state.logs[date]||{};const low=log.energy<=2||log.sleep<=2;
 const recent=Object.keys(state.plans).filter(d=>d<date).sort().reverse().slice(5).map(d=>state.plans[d].actionId);
 const candidates=Object.entries(state.areas).filter(([_,v])=>v>0).map(([area,priority])=>{let score=priority*1.8+Math.min(7,daysSince(area,date))*.9+(seed(date+area)%100)/100;
 if(day>=1&&day<=5&&area==='work')score+=1.5;if((day===0||day===6)&&area==='family')score+=1.5;
 if(area==='recovery'&&low)score+=4;if(area==='training'&&low)score-=1;
 if(area==='family')score+=.35;return {area,score};}).sort((a,b)=>b.score-a.score);
 const area=candidates[0]?.area||'recovery';
 const pool=ACTIONS.map(x=>actionById[x[0]]).filter(a=>a.area===area&&(low?a.effort===1:a.effort>=2));
 const fallback=ACTIONS.map(x=>actionById[x[0]]).filter(a=>a.area===area);
 const choose=(pool.length?pool:fallback).sort((a,b)=>Number(recent.includes(a.id))-Number(recent.includes(b.id))||(seed(date+a.id)%1000)-(seed(date+b.id)%1000));
 return {area,actionId:(choose[0]||actionById.r1).id};
}
function getPlan(date=today()){if(state.plans[date])return state.plans[date];const generated=computePlan(date);const plan={...generated,createdAt:new Date().toISOString()};state.plans[date]=plan;persist();return plan;}
function getAction(date=today()){return resolvedAction(getPlan(date).actionId);}
function getOtherActions(){const main=getAction();const keys=Object.keys(state.areas).filter(k=>state.areas[k]>0&&k!==main.area);const low=state.logs[today()]?.energy<=2;return keys.sort((a,b)=>state.areas[b]-state.areas[a]).slice(0,2).map(area=>ACTIONS.map(x=>actionById[x[0]]).filter(a=>a.area===area&&(low?a.effort===1:a.effort<=2))[0]).filter(Boolean);}
function syncReminders(){if(!window.NesteAndroid?.updateReminder)return;for(const [key,r] of Object.entries(state.reminders)){const [h,m]=r.time.split(':').map(Number);try{window.NesteAndroid.updateReminder(key,h,m,!!r.on)}catch(e){console.warn('native schedule failed',e)}}syncAdvice();}
function syncAdvice(){if(!window.NesteAndroid?.setDailyAdvice)return;for(let i=0;i<7;i++){const d=new Date();d.setDate(d.getDate()+i);const date=localDay(d);const item=resolvedAction(state.plans[date]?.actionId||computePlan(date).actionId);try{window.NesteAndroid.setDailyAdvice(date,item.title,item.description)}catch(e){console.warn(e)}}}
function screenMinutes(){if(!window.NesteAndroid?.getScreenTimeMinutes)return null;try{return Number(window.NesteAndroid.getScreenTimeMinutes());}catch(e){return null;}}

function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.classList.remove('show'),2600)}
function brand(){return `<div class="brand"><div class="brand-mark">N</div><div><div class="brand-name">NESTE</div><div class="brand-tagline">En ting av gangen.</div></div></div>`}
function navItem(k,label,icon){return `<button class="nav-link ${screen===k?'active':''}" data-go="${k}">${ico(icon)} ${label}</button>`}
function mobileNav(k,label,icon){return `<button class="bottom-link ${screen===k?'active':''}" data-go="${k}">${ico(icon)}<span>${label}</span></button>`}
function shell(content){return `<div class="shell"><aside class="sidebar">${brand()}<nav class="nav-links" aria-label="Hovedmeny">${navItem('today','I dag','home')}${navItem('plan','Min plan','calendar')}${navItem('progress','Utvikling','chart')}${navItem('settings','Innstillinger','user')}</nav><div class="sidebar-bottom"><strong>Små steg. Ekte fremgang.</strong>Ingen poeng eller dårlige samvittigheter.<br>Kun det som hjelper deg videre.</div></aside><main class="main"><div class="main-inner"><header class="mobile-head">${brand()}<button class="btn sm" data-go="settings" aria-label="Innstillinger">${ico('settings')}</button></header>${content}<footer class="footnote">NESTE · Privat på enheten din · Ikke medisinsk rådgivning</footer></div></main><nav class="bottom-nav" aria-label="Hovedmeny">${mobileNav('today','I dag','home')}${mobileNav('plan','Plan','calendar')}${mobileNav('progress','Utvikling','chart')}${mobileNav('settings','Meg','user')}</nav></div>`;}
function header(title,subtitle){return `<div class="page-head"><div><p class="date-label">${esc(dayLabel(today()))}</p><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="top-symbol">${ico('spark','big')}</div></div>`;}
function todayView(){const d=today(),log=state.logs[d]||{},a=getAction(),result=log.result,others=getOtherActions(),minutes=screenMinutes();const greeting='God '+(new Date().getHours()<12?'morgen':new Date().getHours()<17?'ettermiddag':'kveld')+(state.name?', '+esc(state.name):'')+'.';
return shell(`${header(greeting,'Du trenger ikke forbedre alt i dag. Vi begynner med det som betyr mest.')}
<div class="grid-layout"><div class="left-stack"><section class="card hero"><div class="hero-row"><span class="eyebrow light">Dagens viktigste handling</span><span class="round-tag">${ico(SYMBOLS[a.area],'mini')} ${esc(LABELS[a.area])}</span></div><h2>${result==='done'?'Du gjorde det som telte.':result==='small'?'Et lite steg er også et steg.':result==='skip'?'Du valgte å utsette bevisst.':esc(a.title)}</h2><p>${result?'Dagens handling er registrert. Det er ikke nødvendig å fylle dagen med flere krav.':esc(a.description)}</p>${showWhy&&!result?`<div class="why"><strong>Hvorfor dette?</strong><br>${esc(a.why)} Anbefalingen er regelbasert og justeres etter dine registreringer.</div>`:''}
<div class="hero-bottom">${result?`<button class="btn hero-btn" data-go="progress">${ico('chart')} Se utvikling</button><button class="btn dark-outline" data-act="undo">Angre</button>`:`<button class="btn hero-btn" data-act="done">${ico('check')} Jeg gjorde det</button><button class="btn dark-outline" data-act="adjust">Tilpass</button><button class="btn dark-outline" data-act="timer">${ico('clock','mini')} 5 min</button>${a.area==='training'?`<button class="btn dark-outline" data-act="training-guide">${ico('activity','mini')} Øvelser</button>`:''}<button class="btn dark-outline" data-act="why">${ico('info','mini')} Hvorfor?</button>`}</div></section>
<section class="card"><div class="card-top"><h2 class="card-title">Dagens innsjekk</h2><span class="eyebrow">20 sekunder</span></div><div class="checkin">${rating('energy','Energi',log.energy,['Helt tom','Lav','Middels','God','Mye'])}${rating('sleep','Søvn siste natt',log.sleep,['Svært dårlig','Dårlig','Middels','God','Svært god'])}</div><div class="divider"></div><div class="row-between"><p class="note" style="margin:0">${log.energy&&log.sleep?'Lagret. Rådet justeres etter kapasiteten din.':'Velg ett tall på hver. Ingen daglig skjema-plikt.'}</p><button class="btn sm" data-act="save-checkin" ${!log.energy||!log.sleep?'disabled':''}>${ico('check','mini')} Lagre</button></div></section>
<section class="card"><div class="card-top"><h2 class="card-title">Andre gode muligheter</h2><span class="eyebrow">Helt frivillig</span></div>${others.map(x=>`<div class="action-row"><div class="action-row-left"><div class="action-icon">${ico(SYMBOLS[x.area])}</div><div><p class="action-row-title">${esc(x.title)}</p><p class="action-row-copy">${esc(LABELS[x.area])} · ${x.effort===1?'2–5':'5–15'} min</p></div></div><button class="btn sm" data-optional="${x.id}">Velg</button></div>`).join('')||'<p class="note">Aktiver flere fokusområder under Min plan.</p>'}</section></div>
<div class="right-stack"><section class="card card-tight"><div class="card-top"><h2 class="card-title">Denne uken</h2>${ico('chart')}</div>${metricHtml()}<div class="divider"></div><div class="row-between"><span class="kicker">${ico('clock','mini')} Ingen krav om en perfekt rekke</span><button class="minor-link" data-go="progress">Se mer</button></div></section>
<section class="card card-tight"><div class="card-top"><h2 class="card-title">Skjermtid i dag</h2>${ico('phone')}</div>${minutes===null?'<p class="note">I nettutgaven kan skjermtid ikke leses automatisk. I Android-appen kan du velge å gi tilgang.</p>':minutes<0?`<p class="note">Gi NESTE tilgang til bruksstatistikk hvis du ønsker et anslag over dagens appbruk.</p><button class="btn sm" data-act="usage-access">${ico('settings','mini')} Koble til skjermtid</button>`:`<div class="small-stat">${Math.floor(minutes/60)}<span style="font:normal 17px var(--font)"> t </span>${minutes%60}<span style="font:normal 17px var(--font)"> min</span></div><p class="stat-note">Anslag fra Androids bruksstatistikk, ikke presis skjerm-på-tid.</p>`}</section><section class="card card-tight"><div class="card-top"><h2 class="card-title">Husk å følge opp</h2><button class="minor-link" data-go="plan">Alle oppgaver</button></div>${taskPreview()}</section>
<div class="callout">${ico('moon','big')}<div><strong>En viktig påminnelse</strong><p>${log.energy<=2||log.sleep<=2?'I dag har du registrert lav kapasitet. Det er lov å gjøre mindre.': 'Bedre vaner kommer av flere gjennomførbare øyeblikk, ikke flere krav.'}</p></div></div>
<section class="card card-tight"><div class="card-top"><h2 class="card-title">Avslutt dagen</h2>${ico('sun')}</div><p class="note" style="margin:0 0 16px">Et kort tilbakeblikk. Hva hjalp? Hva var vanskelig?</p><button class="btn" data-act="reflection">${log.reflection?'Endre refleksjon':'Ta kveldsrefleksjonen'} ${ico('arrow','mini')}</button></section></div></div>`);
}
function rating(key,title,value,labels){return `<div class="rating-block"><div class="rating-head"><span>${title}</span><span class="rating-text">${value?labels[value-1]:'Ikke valgt'}</span></div><div class="rating-buttons" role="group" aria-label="${title}">${[1,2,3,4,5].map(n=>`<button class="rating-btn ${value===n?'selected':''}" aria-pressed="${value===n}" data-rating="${key}:${n}">${n}</button>`).join('')}</div></div>`}
function weeklyEntries(offset=0){const start=new Date();start.setHours(12,0,0,0);const delta=(start.getDay()+6)%7;start.setDate(start.getDate()-delta+(offset*7));return Array.from({length:7},(_,i)=>{const dt=new Date(start);dt.setDate(start.getDate()+i);return {date:localDay(dt),day:SHORT_DAYS[dt.getDay()],log:state.logs[localDay(dt)]||{}}});}
function metricHtml(){const week=weeklyEntries(),logged=week.filter(x=>!!x.log.result),count=logged.filter(x=>['done','small'].includes(x.log.result)).length,checkins=week.filter(x=>x.log.energy&&x.log.sleep).length;return `<div class="metric-pair"><div><div class="eyebrow">Handlinger</div><div class="small-stat">${count}<span style="font:normal 13px var(--font);color:var(--muted)"> / ${logged.length}</span></div><p class="stat-note">Gjort / vurdert</p></div><div><div class="eyebrow">Innsjekker</div><div class="small-stat">${checkins}<span style="font:normal 13px var(--font);color:var(--muted)"> / 7</span></div><p class="stat-note">Denne uken</p></div></div>`;}
function taskPreview(){const open=state.tasks.filter(t=>!t.done).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,3);return open.length?open.map(t=>`<div class="action-row"><div style="min-width:0"><p class="action-row-title">${esc(t.title)}</p><p class="action-row-copy">${t.due?esc(dayLabel(t.due)):esc(LABELS[t.area]||'Annet')}</p></div><button class="task-complete" data-task-done="${esc(t.id)}" aria-label="Fullfør ${esc(t.title)}">${ico('check','mini')}</button></div>`).join(''):`<div class="empty-state" style="padding:20px 15px"><strong>Ingenting å holde styr på nå.</strong>Legg til ting du vil ta initiativ til.</div><button class="btn sm" style="margin-top:12px" data-act="new-task">${ico('plus','mini')} Ny oppgave</button>`;}
function focusCard(area){const pr=state.areas[area];return `<article class="card focus-card ${pr===0?'disabled':''}"><div class="focus-top"><div class="action-icon">${ico(SYMBOLS[area])}</div><button class="toggle ${pr?'on':''}" data-toggle-area="${area}" aria-label="${pr?'Slå av':'Slå på'} ${esc(LABELS[area])}" aria-pressed="${!!pr}"></button></div><div><h3>${esc(LABELS[area])}</h3><p style="margin-top:5px">${esc(DESCRIPTIONS[area])}</p></div><div class="focus-meta">${pr===0?'Satt på pause':pr===3?'Høy prioritet':pr===2?'Middels prioritet':'Lav prioritet'} ${pr?`· <button class="minor-link" data-priority="${area}">Endre</button>`:''}</div></article>`}
function planView(){return shell(`${header('Min plan.','Vi bygger proaktivitet med små, konkrete forpliktelser — ikke en uendelig liste.')}
<div class="section-head" style="margin-top:0"><h2>Områder å utvikle</h2><span class="note">Trykk for å justere</span></div><div class="focus-grid">${Object.keys(LABELS).map(focusCard).join('')}</div><div class="section-head"><h2>Ta initiativ</h2><button class="btn primary sm" data-act="new-task">${ico('plus','mini')} Legg til</button></div><div class="card"><div class="row-between" style="margin-bottom:13px"><div><h3 class="subheading">Ting jeg vil følge opp</h3><p class="note" style="margin:0">Et sted for oppgaver du ellers kan glemme.</p></div><span class="eyebrow">${state.tasks.filter(t=>!t.done).length} åpne</span></div><div class="task-list">${state.tasks.length?state.tasks.slice().sort((a,b)=>Number(a.done)-Number(b.done)||(a.due||'9999').localeCompare(b.due||'9999')).map(t=>`<div class="task ${t.done?'done':''}"><button class="task-complete ${t.done?'done':''}" data-task-done="${esc(t.id)}" aria-label="${t.done?'Gjenåpne':'Fullfør'} ${esc(t.title)}">${t.done?ico('check','mini'):''}</button><div class="task-text"><div class="task-title">${esc(t.title)}</div><div class="task-info">${esc(LABELS[t.area]||'Annet')}${t.due?' · '+esc(dayLabel(t.due)):''}</div></div><button class="btn ghost sm" data-task-delete="${esc(t.id)}" aria-label="Slett ${esc(t.title)}">${ico('trash','mini')}</button></div>`).join(''):'<div class="empty-state"><strong>Gi den fremtidige deg en hjelpende hånd.</strong>Eksempel: Sjekk klær til barnehagen på søndag, avklar en beslutning på jobb, eller planlegg en kort treningsøkt.</div>'}</div></div>
<div class="section-head"><h2>Husk det du lærer</h2><button class="btn primary sm" data-act="new-card">${ico('plus','mini')} Nytt kort</button></div>
<section class="card"><div class="row-between"><div><h3 class="subheading">Repetisjon med egne ord</h3><p class="note" style="margin:0">Legg inn noe du vil huske. Test deg selv etter 1, 3, 7 og 14 dager.</p></div><div class="small-stat">${state.cards.filter(c=>c.due<=today()).length}<span style="font:normal 12px var(--font)"> klare</span></div></div><div class="divider"></div>${state.cards.filter(c=>c.due<=today()).length?`<div class="row-between"><span class="note">${state.cards.filter(c=>c.due<=today()).length} ${state.cards.filter(c=>c.due<=today()).length===1?'kort':'kort'} å hente frem nå.</span><button class="btn sm" data-act="review-card">Test meg ${ico('arrow','mini')}</button></div>`:`<div class="empty-state">${state.cards.length?'Du er oppdatert på repetisjonene. Neste runde kommer på planlagt dato.':'Ingen læringskort ennå. Lag ett med noe du faktisk vil huske.'}</div>`}<p class="note" style="margin:12px 0 0">${state.cards.length} kort totalt · Kun lagret på denne enheten</p></section>
<div class="callout" style="margin-top:18px">${ico('info','big')}<div><strong>Ikke gjør alt på en gang</strong><p>Appen velger normalt bare én prioritert handling per dag. Du kan når som helst slå av et område eller redusere intensiteten.</p></div></div>`);}
function weekChart(week){return `<div class="bar-chart">${week.map(({day,log})=>{const height=log.result==='done'?100:log.result==='small'?55:log.result==='skip'?13:0;return `<div class="bar-col"><div class="bar-base"><div class="bar-fill ${height?'':'empty'}" style="height:${height}%"></div></div><div class="bar-label">${day}</div></div>`}).join('')}</div><div class="row-between" style="margin-top:14px"><span class="note">Full = gjennomført · Halv = forenklet</span><span class="note">Ikke resultatmål</span></div>`}
function progressView(){const week=weeklyEntries(period==='week'?0:-1),past=weeklyEntries(-1),actioned=week.filter(x=>x.log.result),done=actioned.filter(x=>['done','small'].includes(x.log.result)),previous=past.filter(x=>['done','small'].includes(x.log.result)),withEnergy=week.filter(x=>x.log.energy);const en=withEnergy.length?(withEnergy.reduce((s,x)=>s+x.log.energy,0)/withEnergy.length).toFixed(1):'—';const notes=Object.entries(state.logs).filter(([d,l])=>l.result||l.reflection).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,12);
let insight='Vi trenger noen registrerte dager før det er mulig å si noe om mønstre.';if(withEnergy.length>=3&&actioned.length>=3){const low=week.filter(x=>x.log.energy&&x.log.energy<=2),high=week.filter(x=>x.log.energy&&x.log.energy>=4);insight=`Du har registrert ${withEnergy.length} innsjekker denne uken. ${low.length?'Lav energi på '+low.length+' av dagene.':''} ${high.length?'God energi på '+high.length+' av dagene.':''} Se spesielt etter om handlingene oppleves lettere på dager med bedre søvn.`;}else if(actioned.length>0)insight=`Du har vurdert ${actioned.length} ${actioned.length===1?'handling':'handlinger'} denne uken. Registrer også søvn og energi når du orker, så kan du se mulige sammenhenger.`;
return shell(`${header('Se det som virker.','Målingene skal hjelpe deg å forstå hverdagen, ikke gi enda en prestasjonsskala.')}
<div class="row-between" style="margin-bottom:17px"><div class="pills"><button class="pill ${period==='week'?'active':''}" data-period="week">Denne uken</button><button class="pill ${period==='prev'?'active':''}" data-period="prev">Forrige uke</button></div><span class="note">Kun registrerte data</span></div>
<div class="grid-layout"><div class="left-stack"><section class="card"><div class="card-top"><h2 class="card-title">Små steg over tid</h2><span class="eyebrow">Mandag–søndag</span></div>${weekChart(week)}</section><section class="card"><h2 class="card-title" style="margin-bottom:18px">Tidligere handlinger</h2><div class="history-list">${notes.length?notes.map(([d,l])=>`<div class="history-item"><div class="history-date">${esc(new Intl.DateTimeFormat('nb-NO',{day:'numeric',month:'short'}).format(dateFromKey(d)))}</div><div><div class="history-text">${esc(state.plans[d]?resolvedAction(state.plans[d].actionId)?.title||'Dagens handling':'Kveldsrefleksjon')}</div><div class="history-detail">${l.reflection?'«'+esc(l.reflection.slice(0,100))+(l.reflection.length>100?'…':'')+'»':l.energy?'Energi '+l.energy+'/5 · Søvn '+(l.sleep||'—')+'/5':'Ingen innsjekk'}</div></div><span class="history-outcome ${l.result==='skip'?'skip':''}">${l.result==='done'?'Gjort':l.result==='small'?'Liten':l.result==='skip'?'Utsatt':'Notat'}</span></div>`).join(''):'<div class="empty-state"><strong>Her blir utviklingen din synlig.</strong>Ingen historikk ennå. Den bygges av virkelige gjennomføringer.</div>'}</div></section></div>
<div class="right-stack"><section class="card"><div class="card-top"><h2 class="card-title">Ukens tall</h2>${ico('chart')}</div><div class="metric-pair"><div><div class="eyebrow">Gjennomført</div><div class="small-stat">${done.length}</div><p class="stat-note">av ${actioned.length} vurderte</p></div><div><div class="eyebrow">Snittenergi</div><div class="small-stat">${en}</div><p class="stat-note">av 5 · ${withEnergy.length} svar</p></div></div><div class="divider"></div><p class="note" style="margin:0">${period==='week'?'Forrige uke: '+previous.length+' gjennomført.':'Tallene omfatter kun registreringene i perioden.'}</p></section><section class="card"><div class="card-top"><h2 class="card-title">Et mønster å følge</h2>${ico('info')}</div><p style="color:var(--muted);font-size:13px;margin:0">${esc(insight)}</p></section><div class="callout">${ico('shield','big')}<div><strong>Ikke en diagnose</strong><p>Dette er en vanelog, ikke en test for utbrenthet eller sykdom. Ved vedvarende eller økende utmattelse bør du vurdere å snakke med fastlegen.</p></div></div></div></div>`);}
function reminderSetting(id,title,desc){const r=state.reminders[id];return `<div class="action-row" style="align-items:flex-start"><div style="min-width:0;flex:1"><div class="action-row-title">${title}</div><p class="action-row-copy">${desc}</p><input class="input" style="margin-top:10px;width:122px" aria-label="Tidspunkt: ${title}" type="time" value="${esc(r.time)}" data-time="${id}" ${r.on?'':'disabled'}/></div><button class="toggle ${r.on?'on':''}" aria-label="${r.on?'Skru av':'Skru på'} ${title}" aria-pressed="${!!r.on}" data-reminder="${id}"></button></div>`}
function settingsView(){const native=!!window.NesteAndroid;return shell(`${header('Ditt tempo.','Du bestemmer hvor mye appen skal gripe inn i hverdagen.')}
<div class="grid-layout"><div class="left-stack"><section class="card"><div class="card-top"><h2 class="card-title">Når bør jeg minne deg på noe?</h2>${ico('clock')}</div><p class="note" style="margin:0 0 14px">Varsler er ment som en vennlig dytt, ikke avbrytelser du må svare på.</p>${reminderSetting('morning','Før arbeidsdagen','Et konkret første steg for dagen.')}${reminderSetting('home','Når dagen skifter','Ta initiativ hjemme eller legg fra deg skjermen.')}${reminderSetting('evening','Valgfri kveldsrefleksjon','Ett spørsmål om hva som fungerte.')}
<div class="divider"></div><div class="banner">${ico('info') }<span>${native?'Android-varsler styres av telefonens tillatelser. De fungerer også når appen er lukket, men kan bli forsinket av batterisparing.':'I denne nettutgaven lagres tidspunktene, men bakgrunnsvarsler er ikke pålitelige når nettleseren er lukket. Installer Android-appen for planlagte systemvarsler.'}</span></div>${native?`<button class="btn" style="margin-top:15px" data-act="notification-permission">${ico('settings','mini')} Tillat varsler på Android</button>`:''}</section>
<section class="card"><div class="card-top"><h2 class="card-title">Personlig</h2>${ico('user')}</div><div class="field"><label for="username">Hva vil du bli kalt? (valgfritt)</label><input class="input" id="username" maxlength="32" placeholder="Fornavn" value="${esc(state.name)}"/></div><div class="row-between" style="margin-top:15px"><p class="note" style="margin:0">Kun lagret på denne enheten.</p><button class="btn sm" data-act="save-name">Lagre</button></div></section></div>
<div class="right-stack"><section class="card"><div class="card-top"><h2 class="card-title">Dine data</h2>${ico('shield')}</div><p class="note">Alt lagres lokalt. Ingen konto, analyseverktøy eller datadeling er aktivert. Du eier registreringene.</p><div class="stack" style="margin-top:16px"><button class="btn" data-act="export">${ico('export')} Eksporter data</button><button class="btn" data-act="import">${ico('refresh')} Importer sikkerhetskopi</button><button class="btn danger" data-act="clear">${ico('trash')} Slett lokale data</button></div></section><section class="card"><div class="card-top"><h2 class="card-title">Om NESTE</h2>${ico('info')}</div><p class="note">Versjon 1.0 · Personlig handlingscoach</p><p class="note">Anbefalingene er basert på tydelige regler, dine prioriteringer og egne registreringer. Dette er ikke en språkmodell som analyserer deg i bakgrunnen.</p><p class="note">Forslagene er selvhjelp og ikke medisinske råd. Søvnvansker, langvarig utmattelse eller tydelig funksjonsfall kan være grunn til å kontakte fastlege.</p></section></div></div>`);}
function onboarding(){return `<div class="onboard-wrap"><div class="onboard-aside"><div>${brand()}<h1>Litt mer av det livet du vil leve.</h1><p>En personlig coach som tar initiativ. Ett overkommelig steg om gangen — på jobb, hjemme og for deg selv.</p></div><span class="onboard-tag">Ingen konto. Ingen prestasjonsjag.</span></div><div class="onboard-content"><div class="eyebrow">Kom i gang · ${onboardingStep+1} av 2</div><h2>${onboardingStep===0?'Hva vil du ha mer av?':'Når passer det med et lite dytt?'}</h2><p>${onboardingStep===0?'Velg områdene du ønsker å utvikle. Vi foreslår en rolig start, ikke en ny liste med plikter.':'Start med ett eller to påminnelsestidspunkt. Du kan endre alt senere.'}</p><div class="card">${onboardingStep===0?`<div class="stack" style="gap:10px">${Object.keys(LABELS).map(a=>`<div class="row-between" style="padding:6px 0"><div class="row"><div class="action-icon">${ico(SYMBOLS[a])}</div><span style="font-size:13px;font-weight:700">${esc(LABELS[a])}</span></div><button class="toggle ${state.areas[a]?'on':''}" data-toggle-area="${a}" aria-pressed="${!!state.areas[a]}" aria-label="${esc(LABELS[a])}"></button></div>`).join('')}</div>`:`<div class="stack">${reminderSetting('morning','Morgen','Dagens første steg')}${reminderSetting('home','Ettermiddag','Hjem og familie')}<div class="field"><label for="onboard-name">Fornavn (valgfritt)</label><input class="input" id="onboard-name" maxlength="32" placeholder="Hva vil du bli kalt?" value="${esc(state.name)}" /></div></div>`}<div class="row-between" style="margin-top:24px"><span class="note">Du kan endre dette når som helst.</span><button class="btn primary" data-act="onboard-next">${onboardingStep===0?'Neste':'Start NESTE'} ${ico('arrow','mini')}</button></div></div></div></div>`;}
function modalHtml(){if(!modal)return '';let inner='';const a=getAction();
if(modal==='adjust')inner=`<div class="eyebrow">Gjør det gjennomførbart</div><h2>Velg det som passer i dag.</h2><p>Et lite steg er bedre enn et tiltak som blir enda en belastning.</p><div class="stack" style="margin-top:18px"><button class="btn" data-act="smaller">${ico('minus')} Gjør det mindre (2–5 min)</button><button class="btn" data-act="switch">${ico('refresh')} Bytt til noe annet</button><button class="btn" data-act="skip">${ico('moon')} Ikke i dag</button></div>`;
if(modal==='done')inner=`<div class="eyebrow">Dagens handling</div><h2>Hvordan gikk det?</h2><p>${esc(a.title)}</p><div class="stack" style="margin-top:18px"><button class="btn primary" data-act="mark-done">${ico('check')} Jeg gjennomførte</button><button class="btn" data-act="mark-small">${ico('minus')} Jeg gjorde en mindre versjon</button><button class="btn" data-act="skip">Jeg valgte å la være i dag</button></div>`;
if(modal==='reflection')inner=`<div class="eyebrow">Kveldsrefleksjon</div><h2>Hva fungerte i dag?</h2><p>En setning holder. Ikke nødvendig å analysere alt.</p><form id="reflection-form"><textarea class="textarea" name="reflection" maxlength="500" placeholder="Noe som hjalp, en liten seier eller noe du vil prøve annerledes…">${esc(state.logs[today()]?.reflection||'')}</textarea><div class="modal-actions"><button class="btn primary" type="submit">Lagre refleksjon</button><button class="btn" type="button" data-act="close-modal">Avbryt</button></div></form>`;
if(modal==='new-task')inner=`<div class="eyebrow">Ta initiativ</div><h2>Hva vil du huske å gjøre?</h2><form id="task-form" class="stack"><div class="field"><label for="task-title">Konkret oppgave</label><input class="input" id="task-title" name="title" maxlength="130" required placeholder="F.eks. sjekke vinterklær til barnehagen"/></div><div class="form-row"><div class="field"><label for="task-area">Område</label><select class="select" id="task-area" name="area">${Object.entries(LABELS).map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select></div><div class="field"><label for="task-due">Dato (valgfritt)</label><input class="input" id="task-due" name="due" type="date"/></div></div><div class="modal-actions"><button class="btn primary" type="submit">Legg til oppgave</button><button class="btn" type="button" data-act="close-modal">Avbryt</button></div></form>`;
if(modal==='priority')inner=`<div class="eyebrow">Prioritering</div><h2>${esc(LABELS[modalData.area])}</h2><p>Hvor mye skal dette temaet påvirke de daglige forslagene?</p><div class="stack" style="margin-top:20px">${[[1,'Rolig — av og til'],[2,'Vanlig — jevnlig'],[3,'Viktig — ofte']].map(([v,t])=>`<button class="btn ${state.areas[modalData.area]===v?'primary':''}" data-set-priority="${v}">${t}</button>`).join('')}</div>`;
if(modal==='import')inner=`<div class="eyebrow">Sikkerhetskopi</div><h2>Importer data</h2><p>Lim inn JSON-innholdet fra en tidligere NESTE-eksport. Eksisterende data blir erstattet.</p><form id="import-form"><textarea class="textarea" style="min-height:170px" name="json" required placeholder='{ "schema": 1, … }'></textarea><div class="modal-actions"><button class="btn primary" type="submit">Importer og erstatt</button><button class="btn" type="button" data-act="close-modal">Avbryt</button></div></form>`;
if(modal==='clear')inner=`<div class="eyebrow">Personvern</div><h2>Slette alt?</h2><p>Alle innsjekker, planer, oppgaver og påminnelser fjernes fra denne enheten. Dette kan ikke angres uten en eksport.</p><div class="modal-actions"><button class="btn danger" data-act="confirm-clear">Slett alt</button><button class="btn" data-act="close-modal">Behold data</button></div>`;
if(modal==='training-guide')inner=`<div class="eyebrow">Bevegelse på ditt nivå</div><h2>En rolig økt hjemme.</h2><p>Forslag på rundt 12 minutter. Gjør øvelsene innenfor komfortabel bevegelighet. Kutt ned eller stopp ved smerte, svimmelhet eller ubehag.</p><div class="stack" style="margin-top:18px"><div class="subtle-panel"><strong>01 · Kom i gang · 2 min</strong><p style="margin:5px 0 0">Rolig gange på stedet og lette skulderbevegelser.</p></div><div class="subtle-panel"><strong>02 · Mobilitet · 3 min</strong><p style="margin:5px 0 0">Rolige hoftebevegelser og forsiktig bøy/strekk, uten å presse ytterstilling.</p></div><div class="subtle-panel"><strong>03 · Styrke · 5 min</strong><p style="margin:5px 0 0">2 × 6 kontrollerte sitte–reise fra stol og 2 × 6 lette hoftebøy uten vekt. Ta pauser ved behov.</p></div><div class="subtle-panel"><strong>04 · Avslutt · 2 min</strong><p style="margin:5px 0 0">Rolig gange og pust i behagelig tempo.</p></div></div><div class="modal-actions"><button class="btn primary" data-act="timer">${ico('clock')} Start 5 min</button><button class="btn" data-act="close-modal">Lukk</button></div>`;
if(modal==='new-card')inner=`<div class="eyebrow">Aktiv hukommelse</div><h2>Hva vil du huske?</h2><p>Lag et konkret spørsmål som du kan svare på uten å slå opp.</p><form id="card-form" class="stack"><div class="field"><label for="memory-q">Spørsmål</label><input class="input" name="question" id="memory-q" maxlength="200" required placeholder="F.eks. Hva var hovedideen i møtet?"/></div><div class="field"><label for="memory-a">Svar eller forklaring</label><textarea class="textarea" name="answer" maxlength="900" required placeholder="Skriv det du vil hente frem senere."></textarea></div><div class="modal-actions"><button type="submit" class="btn primary">Opprett læringskort</button><button type="button" class="btn" data-act="close-modal">Avbryt</button></div></form>`;
if(modal==='review-card'){const c=state.cards.filter(c=>c.due<=today()).sort((a,b)=>a.due.localeCompare(b.due))[0];if(!c){modal='';return '';}modalData.cardId=c.id;inner=`<div class="eyebrow">Hent frem fra hukommelsen</div><h2>${esc(c.question)}</h2><p>Prøv å svare før du viser fasiten.</p>${modalData.revealed?`<div class="subtle-panel" style="margin-top:18px"><div class="eyebrow">Ditt svar</div><p style="color:var(--ink);white-space:pre-wrap">${esc(c.answer)}</p></div><div class="modal-actions"><button class="btn primary" data-act="review-good">${ico('check','mini')} Jeg husket det</button><button class="btn" data-act="review-again">Trenger repetisjon</button></div>`:`<div class="modal-actions"><button class="btn primary" data-act="review-reveal">Vis svaret</button></div>`}`;}
if(modal==='timer')inner=`<div class="eyebrow">Hjelp til å begynne</div><h2>Bare de neste minuttene.</h2><p>Sett en kort økt. Du trenger ikke fullføre hele oppgaven.</p><div class="small-stat" id="timer-display" style="font-size:70px;text-align:center;margin:24px 0">${timerText()}</div><div class="modal-actions"><button class="btn primary" data-act="timer-start">${ico('play')} Start 5 minutter</button><button class="btn" data-act="timer-stop">Nullstill</button></div>`;
return `<div class="modal-backdrop" data-overlay="1"><div class="modal" role="dialog" aria-modal="true" aria-label="Dialog"><div class="row-between"><span></span><button class="btn ghost sm" data-act="close-modal" aria-label="Lukk">${ico('close')}</button></div>${inner}</div></div>`;
}
function timerText(){const ms=Math.max(0,timer.until-Date.now());const s=timer.until?Math.ceil(ms/1000):300;return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function render(){const app=document.getElementById('app');app.innerHTML=(state.onboarded?({today:todayView,plan:planView,progress:progressView,settings:settingsView}[screen]||todayView)():onboarding())+modalHtml();document.title='NESTE · '+(state.onboarded?{today:'I dag',plan:'Min plan',progress:'Utvikling',settings:'Innstillinger'}[screen]:'Velkommen');}
function go(k){screen=k;modal='';showWhy=false;render();window.scrollTo({top:0,behavior:'instant'})}
function changePlan(reason){const date=today();const old=getAction();const low=reason==='smaller'||state.logs[date]?.energy<=2;let pool=ACTIONS.map(x=>actionById[x[0]]).filter(a=>a.id!==old.id&&state.areas[a.area]>0&&(reason==='smaller'?a.effort===1:(low?a.effort<=2:true)));
if(reason==='smaller'){const same=pool.filter(a=>a.area===old.area);if(same.length)pool=same;}
if(!pool.length){toast('Ingen andre forslag er aktive.');return;}const choice=pool.sort((a,b)=>(seed(date+a.id+old.id)%1000)-(seed(date+b.id+old.id)%1000))[0];state.plans[date]={...state.plans[date],area:choice.area,actionId:choice.id,adjusted:reason};persist();syncAdvice();modal='';render();toast(reason==='smaller'?'Forslaget er gjort lettere.':'Her er et nytt forslag.');}
function result(mode){const d=today();state.logs[d]={...(state.logs[d]||{}),result:mode,at:new Date().toISOString()};if(mode==='done'&&state.plans[d]?.actionId.startsWith('task:')){const task=state.tasks.find(t=>t.id===state.plans[d].actionId.slice(5));if(task){task.done=true;task.finishedAt=new Date().toISOString();}}persist();syncAdvice();modal='';render();toast(mode==='done'?'Bra. Dagens handling er registrert.':mode==='small'?'Et lite steg er registrert.':'Helt greit. Dagen er registrert uten press.');}
function exportData(){const raw=JSON.stringify(state,null,2);if(window.NesteAndroid?.shareData){window.NesteAndroid.shareData(raw);toast('Åpner Android-deling…');return;}const blob=new Blob([raw],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`neste-backup-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Eksportert som JSON.');}
function onClick(e){const el=e.target.closest('button,[data-overlay]');if(!el)return;
if(el.dataset.overlay&&e.target===el){modal='';render();return;}
if(el.dataset.go){go(el.dataset.go);return}
if(el.dataset.rating){const [key,n]=el.dataset.rating.split(':');const d=today();state.logs[d]={...(state.logs[d]||{}),[key]:Number(n)};if(!state.logs[d].result)delete state.plans[d];persist();render();return;}
if(el.dataset.taskDone){const t=state.tasks.find(x=>x.id===el.dataset.taskDone);if(t){t.done=!t.done;t.finishedAt=t.done?new Date().toISOString():null;persist();syncAdvice();render();toast(t.done?'Oppgaven er fullført.':'Oppgaven er gjenåpnet.')}return;}
if(el.dataset.taskDelete){const id=el.dataset.taskDelete;const t=state.tasks.find(x=>x.id===id);if(t&&confirm(`Slette «${t.title}»?`)){state.tasks=state.tasks.filter(x=>x.id!==id);persist();syncAdvice();render()}return;}
if(el.dataset.toggleArea){const a=el.dataset.toggleArea;state.areas[a]=state.areas[a]?0:2;if(Object.values(state.areas).every(v=>!v))state.areas.recovery=1;delete state.plans[today()];persist();syncAdvice();render();return;}
if(el.dataset.priority){modal='priority';modalData={area:el.dataset.priority};render();return;}
if(el.dataset.setPriority){state.areas[modalData.area]=Number(el.dataset.setPriority);delete state.plans[today()];persist();syncAdvice();modal='';render();return;}
if(el.dataset.reminder){const r=state.reminders[el.dataset.reminder];r.on=!r.on;persist();syncReminders();render();toast(r.on?'Påminnelsen er på.':'Påminnelsen er av.');return;}
if(el.dataset.optional){const a=actionById[el.dataset.optional];if(a){state.plans[today()]={area:a.area,actionId:a.id,adjusted:'optional'};if(state.logs[today()]?.result){delete state.logs[today()].result;}persist();syncAdvice();screen='today';render();window.scrollTo({top:0,behavior:'instant'});toast('Forslaget er valgt for i dag.')}return;}
const act=el.dataset.act;if(!act)return;
switch(act){
case 'onboard-next': if(onboardingStep===0){onboardingStep=1;render()}else{const inp=document.getElementById('onboard-name');state.name=(inp?.value||'').trim().slice(0,32);state.onboarded=true;persist();syncReminders();render();window.scrollTo({top:0,behavior:'instant'});toast('Velkommen til NESTE.');}break;
case 'why':showWhy=!showWhy;render();break;
case 'save-checkin':{const d=today(),log=state.logs[d]||{};if(log.energy&&log.sleep){state.logs[d].checkinAt=new Date().toISOString();delete state.plans[d];persist();getPlan(d);syncAdvice();render();toast('Innsjekken er lagret.')}}break;
case 'adjust':case 'done':case 'reflection':case 'new-task':case 'import':case 'clear':case 'timer':case 'training-guide':case 'new-card':modal=act;render();break;
case 'review-card':modalData={revealed:false};modal='review-card';render();break;
case 'review-reveal':modalData.revealed=true;render();break;
case 'review-good':case 'review-again':{const c=state.cards.find(x=>x.id===modalData.cardId);if(c){c.level=act==='review-good'?Math.min(5,(c.level||0)+1):0;const intervals=[1,3,7,14,30,60];const date=new Date();date.setDate(date.getDate()+intervals[c.level]);c.due=localDay(date);c.lastReviewed=new Date().toISOString();persist();}modal='';modalData={};render();toast(act==='review-good'?'Fint. Neste repetisjon er planlagt.':'Vi prøver igjen i morgen.');}break;
case 'close-modal':modal='';render();break;
case 'smaller':changePlan('smaller');break;
case 'switch':changePlan('switch');break;
case 'skip':result('skip');break;
case 'mark-done':result('done');break;
case 'mark-small':result('small');break;
case 'undo':{const d=today();if(state.logs[d])delete state.logs[d].result;persist();render();toast('Markeringen er angret.')}break;
case 'save-name':state.name=document.getElementById('username').value.trim().slice(0,32);persist();render();toast('Lagret.');break;
case 'export':exportData();break;
case 'notification-permission':if(window.NesteAndroid?.requestNotifications){window.NesteAndroid.requestNotifications();toast('Kontroller Android-varselinnstillingene.')}break;
case 'usage-access':if(window.NesteAndroid?.openUsageAccessSettings){window.NesteAndroid.openUsageAccessSettings();toast('Gi NESTE tilgang under Brukstilgang.')}break;
case 'confirm-clear':{for(const r of Object.values(state.reminders))r.on=false;syncReminders();localStorage.removeItem(KEY);state=defaultState();screen='today';onboardingStep=0;modal='';render();toast('Lokale data er slettet.')}break;
case 'timer-start':{timer.until=Date.now()+5*60*1000;clearInterval(timer.interval);timer.interval=setInterval(()=>{const d=document.getElementById('timer-display');if(d)d.textContent=timerText();if(Date.now()>=timer.until){clearInterval(timer.interval);timer.until=0;toast('Fem minutter ferdig. Du bestemmer om du vil fortsette.')}},500);render()}break;
case 'timer-stop':clearInterval(timer.interval);timer.until=0;render();break;
}
}
function onChange(e){const el=e.target;if(el.dataset.time){const r=state.reminders[el.dataset.time];if(/^([01]\d|2[0-3]):[0-5]\d$/.test(el.value)){r.time=el.value;persist();syncReminders();toast('Tidspunktet er oppdatert.')}return;}
if(el.dataset.period){period=el.dataset.period;render();return;}}
function onSubmit(e){if(e.target.id==='reflection-form'){e.preventDefault();const d=today();state.logs[d]={...(state.logs[d]||{}),reflection:String(new FormData(e.target).get('reflection')||'').trim().slice(0,500)};persist();modal='';render();toast('Refleksjonen er lagret.');}
if(e.target.id==='task-form'){e.preventDefault();const f=new FormData(e.target);const title=String(f.get('title')||'').trim();if(!title)return;const area=String(f.get('area')||'family');const due=String(f.get('due')||'');if(due&&!/^\d{4}-\d{2}-\d{2}$/.test(due))return;state.tasks.push({id:'t'+Date.now()+Math.random().toString(36).slice(2,6),title:title.slice(0,130),area:LABELS[area]?area:'family',due,done:false,createdAt:new Date().toISOString()});delete state.plans[today()];persist();syncAdvice();modal='';screen='plan';render();toast('Oppgaven er lagt til.');}
if(e.target.id==='card-form'){e.preventDefault();const f=new FormData(e.target),question=String(f.get('question')||'').trim(),answer=String(f.get('answer')||'').trim();if(!question||!answer)return;state.cards.push({id:'c'+Date.now()+Math.random().toString(36).slice(2,5),question:question.slice(0,200),answer:answer.slice(0,900),due:today(),level:0,createdAt:new Date().toISOString()});persist();modal='';screen='plan';render();toast('Læringskortet er klart til første repetisjon.');}
if(e.target.id==='import-form'){e.preventDefault();try{const raw=String(new FormData(e.target).get('json')||'');const x=JSON.parse(raw);if(x.schema!==1||typeof x.logs!=='object'||!x.areas||!x.reminders||!Array.isArray(x.tasks)||!x.plans)throw Error('Ukjent format');state={...defaultState(),...x};persist();modal='';syncReminders();render();toast('Sikkerhetskopien er importert.');}catch(err){toast('Ugyldig sikkerhetskopi. Ingen data ble endret.')}}}
window.NESTE={refresh:()=>{getPlan();render();if(state.onboarded)syncReminders();},goBack:()=>{if(modal){modal='';render();return true}if(screen!=='today'){go('today');return true}return false},exportData:()=>JSON.stringify(state),version:'1.0.0'};
document.addEventListener('click',e=>{if(e.target.closest('[data-period]')){period=e.target.closest('[data-period]').dataset.period;render();return}onClick(e)});
document.addEventListener('change',onChange);
document.addEventListener('submit',onSubmit);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal='';render()}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){getPlan();render();if(state.onboarded)syncReminders();}});
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
getPlan();render();if(state.onboarded)syncReminders();
})();
